import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s = input_data[1] if len(input_data) > 1 else ""

    if n % 4 != 0:
        print("===")
        return

    target = n // 4

    counts = {'A': 0, 'C': 0, 'G': 0, 'T': 0}
    for char in s:
        if char in counts:
            counts[char] += 1

    if any(count > target for count in counts.values()):
        print("===")
        return

    needed = {char: target - count for char, count in counts.items()}
    total_needed = sum(needed.values())

    q_count = s.count('?')

    if q_count != total_needed:
        print("===")
        return

    result = list(s)
    idx = 0
    chars_to_fill = []

    for char in ['A', 'C', 'G', 'T']:
        for _ in range(needed[char]):
            chars_to_fill.append(char)

    fill_idx = 0
    for i in range(n):
        if result[i] == '?':
            result[i] = chars_to_fill[fill_idx]
            fill_idx += 1

    print("".join(result))

if __name__ == "__main__":
    solve()
